CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,role ENUM('admin','user') DEFAULT 'user',failed_attempts INT DEFAULT 0,locked_until DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS datasets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,file_hash CHAR(64) NOT NULL,imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,file_hash),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS accounts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(80) NOT NULL,is_system TINYINT DEFAULT 0,balance_paise BIGINT NOT NULL DEFAULT 0,UNIQUE(user_id,name),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,txn_ref VARCHAR(80) NOT NULL,date DATE NOT NULL,type VARCHAR(20) NOT NULL,narration VARCHAR(255),amount_paise BIGINT NOT NULL,idem_key VARCHAR(100) NULL,payload_hash CHAR(64) NULL,response_json JSON NULL,reversed_by INT NULL,UNIQUE(user_id,txn_ref),UNIQUE(user_id,idem_key),INDEX(user_id,date),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ledger_entries(id INT AUTO_INCREMENT PRIMARY KEY,txn_id INT NOT NULL,account_id INT NOT NULL,direction ENUM('DEBIT','CREDIT') NOT NULL,amount_paise BIGINT NOT NULL,INDEX(account_id),FOREIGN KEY(txn_id) REFERENCES transactions(id),FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS user_session_state(user_id INT PRIMARY KEY,last_route VARCHAR(200),state_json JSON,version INT DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(40) NOT NULL,meta JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS refresh_tokens(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
